#include <deque>
#include <iostream>
#include <vector>

/* The deque holds INDICES, in decreasing order of their values. The
   front is therefore always the maximum of the current window. */
static std::vector<long long> windowMax(const std::vector<long long>& a, int k) {
    std::vector<long long> out;
    std::deque<int> q;
    for (int i = 0; i < (int) a.size(); ++i) {
        while (!q.empty() && q.front() <= i - k) q.pop_front();
        while (!q.empty() && a[q.back()] <= a[i]) q.pop_back();
        q.push_back(i);
        if (i >= k - 1) out.push_back(a[q.front()]);
    }
    return out;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n = 0, k = 0;
    if (!(std::cin >> n >> k)) return 0;
    std::vector<long long> a(n);
    for (auto& x : a) std::cin >> x;

    if (k <= 0 || k > n) {
        std::cout << "no windows" << '\n';
        return 0;
    }

    const std::vector<long long> m = windowMax(a, k);
    std::cout << m.size() << '\n';
    for (std::size_t i = 0; i < m.size(); ++i) {
        std::cout << m[i] << (i + 1 == m.size() ? '\n' : ' ');
    }
    return 0;
}
